```
count = array of 26 zeros
n = number of words
for each word:
    for each char in word:
        count[char] += 1
for each letter in count:
    if count % n != 0:
        return false
return true
```

code.cpp:
class Solution {
public:
    bool makeEqual(vector<string>& words) {
        int cnt[26] = {0};
        int n = words.size();
        for (const string& w : words) {
            for (char c : w) {
                cnt[c - 'a']++;
            }
        }
        for (int i = 0; i < 26; i++) {
            if (cnt[i] % n != 0) return false;
        }
        return true;
    }
};
